BEGIN;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE categories(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL UNIQUE,slug text NOT NULL UNIQUE,active boolean NOT NULL DEFAULT true);
CREATE TABLE brands(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL UNIQUE);
CREATE TABLE products(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),category_id uuid REFERENCES categories,brand_id uuid REFERENCES brands,slug text NOT NULL UNIQUE,name text NOT NULL,description text NOT NULL DEFAULT '',published boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE variants(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),product_id uuid NOT NULL REFERENCES products,sku text NOT NULL UNIQUE,label text NOT NULL,price_minor bigint NOT NULL CHECK(price_minor>=0),active boolean NOT NULL DEFAULT true,sellable_qty integer NOT NULL DEFAULT 0 CHECK(sellable_qty>=0),committed_qty integer NOT NULL DEFAULT 0 CHECK(committed_qty>=0),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE device_models(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),brand text NOT NULL,model text NOT NULL,model_number text,UNIQUE(brand,model,model_number));
CREATE TABLE compatibility(variant_id uuid NOT NULL REFERENCES variants,device_model_id uuid NOT NULL REFERENCES device_models,fit_note text NOT NULL DEFAULT '',source text NOT NULL,verified_at timestamptz,PRIMARY KEY(variant_id,device_model_id));
CREATE TABLE specifications(variant_id uuid NOT NULL REFERENCES variants,attribute text NOT NULL,value jsonb NOT NULL,source text NOT NULL,verified_at timestamptz,PRIMARY KEY(variant_id,attribute));
CREATE TABLE customers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),auth_subject text UNIQUE,email text,phone_e164 text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE addresses(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),customer_id uuid REFERENCES customers,recipient text NOT NULL,phone_e164 text NOT NULL,district text NOT NULL,city_upazila text NOT NULL,area text NOT NULL,street text NOT NULL,landmark text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),customer_id uuid REFERENCES customers,guest_name text NOT NULL,guest_phone text NOT NULL,guest_email text,address_snapshot jsonb NOT NULL,status text NOT NULL CHECK(status IN ('pending_payment','awaiting_cod_confirmation','confirmed','processing','cancellation_requested','cancelled','completed','exception')),payment_method text NOT NULL CHECK(payment_method IN ('online','cod')),currency char(3) NOT NULL DEFAULT 'BDT' CHECK(currency='BDT'),items_minor bigint NOT NULL CHECK(items_minor>=0),discount_minor bigint NOT NULL DEFAULT 0 CHECK(discount_minor=0),delivery_minor bigint NOT NULL CHECK(delivery_minor>=0),total_minor bigint NOT NULL CHECK(total_minor=items_minor-discount_minor+delivery_minor),policy_version text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE order_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL REFERENCES orders,variant_id uuid NOT NULL REFERENCES variants,sku_snapshot text NOT NULL,name_snapshot text NOT NULL,unit_minor bigint NOT NULL CHECK(unit_minor>=0),quantity integer NOT NULL CHECK(quantity>0),discount_minor bigint NOT NULL DEFAULT 0 CHECK(discount_minor=0),refunded_quantity integer NOT NULL DEFAULT 0 CHECK(refunded_quantity BETWEEN 0 AND quantity),UNIQUE(order_id,variant_id));
CREATE TABLE checkout_idempotency(key text PRIMARY KEY,request_hash text NOT NULL,order_id uuid UNIQUE REFERENCES orders,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE inventory_commitments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL REFERENCES orders,variant_id uuid NOT NULL REFERENCES variants,quantity integer NOT NULL CHECK(quantity>0),kind text NOT NULL CHECK(kind IN ('reservation','committed')),status text NOT NULL CHECK(status IN ('active','dispatched','released','expired')),expires_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(order_id,variant_id));
CREATE TABLE inventory_movements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),variant_id uuid NOT NULL REFERENCES variants,order_id uuid REFERENCES orders,actor_id text NOT NULL,kind text NOT NULL CHECK(kind IN ('receipt','adjustment','dispatch','restock','damage')),quantity_delta integer NOT NULL CHECK(quantity_delta<>0),idempotency_key text NOT NULL UNIQUE,reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE payment_attempts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL REFERENCES orders,provider text NOT NULL,provider_ref text UNIQUE,status text NOT NULL CHECK(status IN ('created','pending','succeeded','failed','expired','reconciliation_required')),amount_minor bigint NOT NULL CHECK(amount_minor>0),currency char(3) NOT NULL CHECK(currency='BDT'),verified_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE funding_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL REFERENCES orders,source text NOT NULL CHECK(source IN ('online','cod_customer_collection')),source_ref text NOT NULL UNIQUE,amount_minor bigint NOT NULL CHECK(amount_minor>0),verified boolean NOT NULL DEFAULT false,verified_by text,verified_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE provider_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),provider text NOT NULL,event_id text NOT NULL,payload_hash text NOT NULL,processing_status text NOT NULL DEFAULT 'pending',received_at timestamptz NOT NULL DEFAULT now(),processed_at timestamptz,UNIQUE(provider,event_id));
CREATE TABLE refunds(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL REFERENCES orders,funding_event_id uuid NOT NULL REFERENCES funding_events,amount_minor bigint NOT NULL CHECK(amount_minor>0),status text NOT NULL CHECK(status IN ('requested','approved','submitting','pending','unknown','succeeded','failed','reconciliation_required')),reason text NOT NULL,idempotency_key text NOT NULL UNIQUE,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE refund_items(refund_id uuid NOT NULL REFERENCES refunds,order_item_id uuid NOT NULL REFERENCES order_items,quantity integer NOT NULL CHECK(quantity>0),amount_minor bigint NOT NULL CHECK(amount_minor>=0),PRIMARY KEY(refund_id,order_item_id));
CREATE TABLE refund_payout_attempts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),refund_id uuid NOT NULL REFERENCES refunds,channel text NOT NULL,status text NOT NULL CHECK(status IN ('pending','unknown','succeeded','failed')),provider_ref text UNIQUE,amount_minor bigint NOT NULL CHECK(amount_minor>0),evidence_ref text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE returns(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL REFERENCES orders,status text NOT NULL CHECK(status IN ('requested','authorized','rejected','in_transit','received','inspecting','resolved')),reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE return_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),return_id uuid NOT NULL REFERENCES returns,order_item_id uuid NOT NULL REFERENCES order_items,quantity integer NOT NULL CHECK(quantity>0),inspection text CHECK(inspection IN ('sellable','damaged','unavailable')),disposition text CHECK(disposition IN ('quarantined','restocked','disposed')),inspected_by text,inspected_at timestamptz);
CREATE TABLE shipments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL UNIQUE REFERENCES orders,status text NOT NULL CHECK(status IN ('unallocated','allocated','picking','packed','dispatched','delivered','delivery_failed','retry_scheduled','return_to_origin','returned_to_store')),tracking_ref text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE cod_collections(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL UNIQUE REFERENCES orders,amount_minor bigint NOT NULL CHECK(amount_minor>0),collected_at timestamptz NOT NULL,proof_ref text NOT NULL,verified_by text NOT NULL,verified_at timestamptz NOT NULL);
CREATE TABLE courier_remittances(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),reference text NOT NULL UNIQUE,amount_minor bigint NOT NULL CHECK(amount_minor>0),received_at timestamptz NOT NULL,recorded_by text NOT NULL);
CREATE TABLE remittance_allocations(remittance_id uuid NOT NULL REFERENCES courier_remittances,collection_id uuid NOT NULL REFERENCES cod_collections,amount_minor bigint NOT NULL CHECK(amount_minor>0),PRIMARY KEY(remittance_id,collection_id));
CREATE TABLE warranty_claims(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_item_id uuid NOT NULL REFERENCES order_items,status text NOT NULL CHECK(status IN ('requested','reviewing','approved','rejected','resolved')),reason text NOT NULL,resolution text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE outbox(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),topic text NOT NULL,payload jsonb NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','processing','delivered','failed')),attempts integer NOT NULL DEFAULT 0,next_attempt_at timestamptz NOT NULL DEFAULT now(),last_error text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),actor_id text NOT NULL,action text NOT NULL,entity_type text NOT NULL,entity_id uuid,reason text,metadata jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX products_published_idx ON products(published,category_id) WHERE published;
CREATE INDEX variants_product_idx ON variants(product_id,active);
CREATE INDEX compatibility_model_idx ON compatibility(device_model_id,variant_id);
CREATE INDEX orders_status_created_idx ON orders(status,created_at);
CREATE INDEX commitments_variant_active_idx ON inventory_commitments(variant_id,status) WHERE status='active';
CREATE INDEX payment_order_status_idx ON payment_attempts(order_id,status);
CREATE INDEX refunds_order_status_idx ON refunds(order_id,status);
CREATE INDEX outbox_retry_idx ON outbox(status,next_attempt_at) WHERE status IN ('pending','failed');
COMMIT;
